  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In zebrafish, U-47700 was detected in all brain samples after 20-min exposure, demonstrating direct blood-brain barrier penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "In rats, AH-7921 showed a brain-to-plasma ratio of 16.6, indicating good brain penetrability after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "In non-human primate PET imaging, AZD2423 showed low brain exposure with SUVpeak 0.4, indicating poor BBB permeability in that compound.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analog and the majority of structurally similar compounds show direct in-vivo CNS penetration (brain detection, high brain-to-plasma ratio, CSF:free 1:1), while the two negative records come from lower-similarity compounds; therefore meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct query-specific in vivo data; predictions rely on analogs with moderate Morgan similarity (0.25-0.37).",
    "One human CSF record showed only 0.6-0.7% of plasma levels, leaving uncertainty about the magnitude of CNS exposure.",
    "Negative NHP PET and mouse PK findings at lower similarity suggest possible chemotype-dependent efflux or low permeability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

